#tabmail-tabs {
  /* Overriding tabbox.css */
  border: 0;
  /* Make sure the drop indicator stays inside the parent boundaries */
  position: relative;

  & .tabmail-tab:first-child .tab-close-button,
  &[closebuttons="activetab"] .tabmail-tab:not([selected]) .tab-close-button {
    display: none;
  }
